<?php
namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest;
class StoreProductRequest extends FormRequest { public function authorize(): bool { return true; } public function rules(): array { return ['catalog_code'=>['nullable','string','max:120'],'name'=>['required','string','max:200'],'description'=>['nullable','string'],'category_id'=>['nullable','integer','exists:tenant.product_categories,id'],'product_collection_id'=>['nullable','integer','exists:tenant.product_collections,id'],'product_collection_line_id'=>['nullable','integer','exists:tenant.product_collection_lines,id'],'is_active'=>['nullable','boolean'],'variants'=>['nullable','array'],'variants.*.sku'=>['required','string','max:150'],'variants.*.auxiliary_code'=>['nullable','string','max:150'],'variants.*.stock'=>['nullable','numeric'],'variants.*.minimum_stock'=>['nullable','numeric'],'variants.*.sale_price'=>['nullable','numeric'],'variants.*.purchase_price'=>['nullable','numeric'],'variants.*.is_active'=>['nullable','boolean'],'variants.*.attribute_value_ids'=>['nullable','array'],'variants.*.attribute_value_ids.*'=>['integer','exists:tenant.product_attribute_values,id']]; } protected function prepareForValidation(): void { $this->merge(['is_active'=>$this->boolean('is_active')]); } }
